func admitQuality(t *testing.T, f *nativeInterpretation, c, v, n int) QualityExperiment {
	t.Helper()
	p, e := f.s.Store.AdmitExperiment(context.Background(), qualitySubmission(t, f, c, v, n))
	requireListening(t, e)
	return p
}
